17: func RemoveFile(ctx context.Context, task *asynq.Task) error {
18: 	var payload RemoveFileTaskPayload
19: 	if err := json.Unmarshal(task.Payload(), &payload); err != nil {
20: 		return err
21: 	}
22: 	fileInfo, err := models.GetRedisFileInfo(payload.FileId)
23: 	if err != nil {
24: 		return err
25: 	}
26: 	if fileInfo == nil {
27: 		return nil
28: 	}
29: 	// 如果文件是上传文件，则需要检查是否还有分享，考虑到比如文件转换这些一次性任务产生的文件需要销毁
30: 	if fileInfo.FileType == models.FileTypeUpload {
31: 		shareIDs, err := models.GetRedisFileShareRelational(payload.FileId)
32: 		if err != nil {
33: 			return err
34: 		}
35: 		if len(shareIDs) > 0 {
36: 			return nil
37: 		}
38: 	}
39: 
40: 	rdb := u.GetRedisClient()
41: 	uploadPath, err := u.GetUploadDirPath()
42: 	if err != nil {
43: 		return err
44: 	}
45: 	filePath := filepath.Join(uploadPath, payload.FileId)
46: 	// 如果是临时文件删除文件夹
47: 	if fileInfo.FileType == models.FileTypeInit {
48: 		filePath += "_tmp"
49: 	}
50: 	if err := rdb.Do(ctx, rdb.B().Hdel().Key("015:fileInfoMap").Field(payload.FileId).Build()).Error(); err != nil {
51: 		return err
52: 	}
53: 	if err := os.RemoveAll(filePath); err != nil {
54: 		return err
55: 	}
56: 	return nil
57: }
