59: func FileJanitor(_ context.Context, _ *asynq.Task) error {
60: 	uploadPath, err := u.GetUploadDirPath()
61: 	if err != nil {
62: 		return err
63: 	}
64: 
65: 	entries, err := os.ReadDir(uploadPath)
66: 	if err != nil {
67: 		return err
68: 	}
69: 
70: 	allFileInfo, err := models.GetRedisFileInfoAll()
71: 	if err != nil {
72: 		return err
73: 	}
74: 
75: 	// Case 1: 本地有但 fileInfoMap 無 → 直接刪除
76: 	for _, entry := range entries {
77: 		name := entry.Name()
78: 		fileId := strings.TrimSuffix(name, "_tmp")
79: 		if _, exists := allFileInfo[fileId]; !exists {
80: 			if err := os.RemoveAll(filepath.Join(uploadPath, name)); err != nil {
81: 				return err
82: 			}
83: 		}
84: 	}
85: 
86: 	// Case 2 & 3: 遍歷 fileInfoMap
87: 	now := time.Now().Unix()
88: 	for fileId, rawInfo := range allFileInfo {
89: 		var info models.RedisFileInfo
90: 		if err := json.Unmarshal([]byte(rawInfo), &info); err != nil {
91: 			continue
92: 		}
93: 
94: 		// Case 2: init 狀態且已過期
95: 		if info.FileType == models.FileTypeInit && info.CreatedAt+info.Expire < now {
96: 			if err := pkgservices.SetFileRemoveTask(fileId, 0); err != nil {
97: 				return err
98: 			}
99: 			continue
100: 		}
101: 
102: 		// Case 3: 已完成上傳但無 share 關係
103: 		if info.FileType == models.FileTypeUpload {
104: 			shareIDs, err := models.GetRedisFileShareRelational(fileId)
105: 			if err != nil {
106: 				return err
107: 			}
108: 			if len(shareIDs) == 0 {
109: 				if err := pkgservices.SetFileRemoveTask(fileId, 0); err != nil {
110: 					return err
111: 				}
112: 			}
113: 		}
114: 	}
115: 
116: 	return nil
117: }
